//! `RevokeToken` over the wire: what revoking a refresh token this emulator issued
//! invalidates, and what it refuses.
//!
//! Four rules are under test.
//!
//! * LINEAGE. "Revokes all of the access tokens generated by, and at the same time as,
//!   the specified refresh token. After a token is revoked, you can't use the revoked
//!   token to access Amazon Cognito user APIs" (`RevokeToken` in this service's model),
//!   so one revocation moves the whole sign-in the named refresh token belongs to — the
//!   tokens minted with it, the tokens a refresh with it minted, and the refresh token a
//!   rotation put in its place — and it moves nothing of any other sign-in.
//! * TOKEN TYPE. "`Token`: The refresh token that you want to revoke" and
//!   `UnsupportedTokenTypeException` is "thrown when an unsupported token is passed to
//!   an operation" (this service's model), so a token this app client issued that is
//!   not a refresh token is refused, while a value it issued no token for revokes
//!   nothing and is still served.
//! * REFUSED AS REVOKED. A revoked refresh token is told apart from a value this
//!   emulator cannot resolve at all, by both operations a refresh token authorizes.
//! * APP CLIENT. "`ClientSecret`: The client secret of the requested app client, if the
//!   client has a secret" (this operation's own doc), and
//!   `UnsupportedOperationException` is "thrown when you attempt to perform an operation
//!   that isn't enabled for the user pool client" (this service's model), which for this
//!   operation is an app client whose stored `EnableTokenRevocation` is off — refused
//!   before the submitted `Token` is looked at, with one fixed sentence.
//!
//! Each table row names the case it asserts.

use bytes::Bytes;
use serde_json::{json, Map, Value};
use smithy_server_runtime::MultiServiceRouter;
use std::sync::Arc;

use service_com_amazonaws_cognitoidentityprovider_awscognitoidentityproviderservice as cognito_idp;

/// This service's SigV4 signing name, the 4th field of a credential scope.
const SIGNING_NAME: &str = "cognito-idp";

/// The local name of this service's Smithy shape, which is the `X-Amz-Target` prefix a
/// client writes.
const TARGET_PREFIX: &str = "AWSCognitoIdentityProviderService";

/// This service's real regional endpoint host.
const ENDPOINT_HOST: &str = "cognito-idp.us-east-1.amazonaws.com";

/// The region the suite's calls are signed for, which is the region the pools they
/// create live in.
const DEFAULT_REGION: &str = "us-east-1";

/// A password satisfying a default pool's password policy.
const GOOD_PASSWORD: &str = "Passw0rd!2024";

/// The operation under test.
const REVOKE: &str = "RevokeToken";

/// The operation that exchanges a refresh token for fresh tokens.
const REFRESH: &str = "GetTokensFromRefreshToken";

/// The wire error code of the refusal an app client answers with when the feature the
/// operation needs is switched off in its stored configuration.
const FEATURE_DISABLED_CODE: &str = "UnsupportedOperationException";

/// The fixed sentence that refusal carries: no part of it is taken from the request or
/// from stored state, so it reads the same for every app client and every token.
const FEATURE_DISABLED_MESSAGE: &str = "This feature is not enabled for this client";

/// A `ClientIdType`-shaped id (pattern `^[\w+]+$`, length 1..128) no create minted.
const UNKNOWN_CLIENT_ID: &str = "nosuchappclient0000";

/// A `ClientSecretType`-shaped secret (pattern `^[\w+]+$`, length 24..64) no app client
/// holds.
const WRONG_CLIENT_SECRET: &str = "wrongsecret0000000000000000";

/// A `TokenModelType`-shaped value (pattern `^[A-Za-z0-9-_=.]+$`) this emulator issued
/// to nobody.
const UNISSUED_TOKEN: &str = "eyJub3QiOiJhLXRva2VuIn0=.not-issued-here.AAAA";

/// One emulator with just this service mounted over a fresh engine.
fn router() -> MultiServiceRouter {
    let engine = Arc::new(engine::InMemoryEngine::new());
    let mut router = MultiServiceRouter::new();
    router.register_service(cognito_idp::EmulatedService::new(engine));
    router
}

/// Dispatch `operation` with `body` and return the status and JSON response body.
async fn dispatch(router: &MultiServiceRouter, operation: &str, body: &Value) -> (u16, Value) {
    let request = http::Request::builder()
        .method("POST")
        .uri("/")
        .header("host", ENDPOINT_HOST)
        .header("content-type", "application/x-amz-json-1.1")
        .header("x-amz-target", format!("{TARGET_PREFIX}.{operation}"))
        .header(
            "authorization",
            format!(
                "AWS4-HMAC-SHA256 Credential=AKIDEXAMPLE/20260101/{DEFAULT_REGION}/{SIGNING_NAME}/aws4_request, \
                 SignedHeaders=host;x-amz-date, Signature=0000"
            ),
        );
    let response = router
        .dispatch(
            request
                .body(Bytes::from(body.to_string()))
                .expect("the request is well formed"),
        )
        .await;
    let status = response.status().as_u16();
    let payload = if response.body().is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(response.body()).unwrap_or_else(|error| {
            panic!(
                "{operation} answered a body that is not JSON ({error}): {:?}",
                String::from_utf8_lossy(response.body())
            )
        })
    };
    (status, payload)
}

/// Call `operation`, requiring success, and return its response body.
async fn ok(router: &MultiServiceRouter, operation: &str, body: &Value) -> Value {
    let (status, payload) = dispatch(router, operation, body).await;
    assert_eq!(
        status, 200,
        "{operation} must succeed, got {status} with {payload}"
    );
    payload
}

/// The `__type` of an error body, which is the wire error code.
fn error_code(payload: &Value) -> &str {
    payload
        .get("__type")
        .and_then(Value::as_str)
        .unwrap_or("<no __type>")
}

/// The `message` of an error body.
fn error_message(payload: &Value) -> &str {
    payload
        .get("message")
        .and_then(Value::as_str)
        .unwrap_or("<no message>")
}

/// Call `operation` expecting a refusal, and assert its status, wire error code and
/// message.
async fn refused(
    router: &MultiServiceRouter,
    case: &str,
    operation: &str,
    body: &Value,
    expected_status: u16,
    expected_code: &str,
    expected_message: &str,
) {
    let (status, payload) = dispatch(router, operation, body).await;
    assert_eq!(
        (status, error_code(&payload), error_message(&payload)),
        (expected_status, expected_code, expected_message),
        "case {case:?}: expected ({expected_status}, {expected_code:?}, {expected_message:?}), \
         got ({status}, {:?}, {:?})",
        error_code(&payload),
        error_message(&payload)
    );
}

/// A created pool and one of its app clients.
struct Fixture {
    user_pool_id: String,
    client_id: String,
    /// The secret the app client was created with, when it asked for one.
    client_secret: Option<String>,
}

/// What an app client of this suite is created with.
#[derive(Default)]
struct ClientSetup {
    /// The client's `RefreshTokenRotation`.
    rotation: Option<Value>,
    /// Whether the client holds a secret.
    generate_secret: bool,
    /// The client's `EnableTokenRevocation`, left unset when `None` (which activates
    /// token revocation).
    enable_token_revocation: Option<bool>,
}

/// Create a pool and one app client as `setup` asks, and return both ids.
async fn pool_with_client(
    router: &MultiServiceRouter,
    pool_name: &str,
    setup: &ClientSetup,
) -> Fixture {
    let created = ok(router, "CreateUserPool", &json!({ "PoolName": pool_name })).await;
    let user_pool_id = created["UserPool"]["Id"]
        .as_str()
        .expect("a minted pool id")
        .to_string();
    let client_id = add_client(router, &user_pool_id, setup).await;
    Fixture {
        user_pool_id,
        client_id: client_id.0,
        client_secret: client_id.1,
    }
}

/// Create one more app client in `user_pool_id`, and return its id and secret.
async fn add_client(
    router: &MultiServiceRouter,
    user_pool_id: &str,
    setup: &ClientSetup,
) -> (String, Option<String>) {
    let mut body = Map::new();
    body.insert("UserPoolId".to_string(), json!(user_pool_id));
    body.insert("ClientName".to_string(), json!("revoke-client"));
    body.insert(
        "ExplicitAuthFlows".to_string(),
        json!(["ALLOW_USER_PASSWORD_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]),
    );
    if let Some(rotation) = setup.rotation.clone() {
        body.insert("RefreshTokenRotation".to_string(), rotation);
    }
    if setup.generate_secret {
        body.insert("GenerateSecret".to_string(), json!(true));
    }
    if let Some(enabled) = setup.enable_token_revocation {
        body.insert("EnableTokenRevocation".to_string(), json!(enabled));
    }
    let client = ok(router, "CreateUserPoolClient", &Value::Object(body)).await;
    (
        client["UserPoolClient"]["ClientId"]
            .as_str()
            .expect("a minted client id")
            .to_string(),
        client["UserPoolClient"]["ClientSecret"]
            .as_str()
            .map(str::to_string),
    )
}

/// Create `username` in `user_pool_id` with a PERMANENT password, so it is `CONFIRMED`
/// and can sign in.
async fn create_confirmed_user(router: &MultiServiceRouter, user_pool_id: &str, username: &str) {
    ok(
        router,
        "AdminCreateUser",
        &json!({ "UserPoolId": user_pool_id, "Username": username }),
    )
    .await;
    ok(
        router,
        "AdminSetUserPassword",
        &json!({
            "UserPoolId": user_pool_id,
            "Username": username,
            "Password": GOOD_PASSWORD,
            "Permanent": true,
        }),
    )
    .await;
}

/// Sign `username` in with its password on `client_id` and return the
/// `AuthenticationResult`.
async fn sign_in(
    router: &MultiServiceRouter,
    client_id: &str,
    client_secret: Option<&str>,
    username: &str,
) -> Value {
    let mut body = Map::new();
    body.insert("ClientId".to_string(), json!(client_id));
    body.insert("AuthFlow".to_string(), json!("USER_PASSWORD_AUTH"));
    body.insert(
        "AuthParameters".to_string(),
        json!({ "USERNAME": username, "PASSWORD": GOOD_PASSWORD }),
    );
    if let Some(secret) = client_secret {
        body.insert("ClientSecret".to_string(), json!(secret));
    }
    let payload = ok(router, "InitiateAuth", &Value::Object(body)).await;
    payload["AuthenticationResult"].clone()
}

/// The named token of an `AuthenticationResult`, which must be there.
fn token(case: &str, result: &Value, member: &str) -> String {
    result[member]
        .as_str()
        .filter(|token| !token.is_empty())
        .unwrap_or_else(|| panic!("case {case:?}: expected a {member}, got {result}"))
        .to_string()
}

/// A `RevokeToken` body for `fixture`, carrying the app client's secret when it holds
/// one.
fn revoke_body(fixture: &Fixture, revoked_token: &str) -> Value {
    let mut body = Map::new();
    body.insert("ClientId".to_string(), json!(fixture.client_id));
    body.insert("Token".to_string(), json!(revoked_token));
    if let Some(secret) = fixture.client_secret.as_deref() {
        body.insert("ClientSecret".to_string(), json!(secret));
    }
    Value::Object(body)
}

/// A `GetTokensFromRefreshToken` body for `fixture`.
fn refresh_body(fixture: &Fixture, refresh_token: &str) -> Value {
    let mut body = Map::new();
    body.insert("ClientId".to_string(), json!(fixture.client_id));
    body.insert("RefreshToken".to_string(), json!(refresh_token));
    if let Some(secret) = fixture.client_secret.as_deref() {
        body.insert("ClientSecret".to_string(), json!(secret));
    }
    Value::Object(body)
}

/// An `InitiateAuth` body that signs in again with `refresh_token`.
fn refresh_sign_in_body(fixture: &Fixture, refresh_token: &str) -> Value {
    let mut body = Map::new();
    body.insert("ClientId".to_string(), json!(fixture.client_id));
    body.insert("AuthFlow".to_string(), json!("REFRESH_TOKEN_AUTH"));
    body.insert(
        "AuthParameters".to_string(),
        json!({ "REFRESH_TOKEN": refresh_token }),
    );
    if let Some(secret) = fixture.client_secret.as_deref() {
        body.insert("ClientSecret".to_string(), json!(secret));
    }
    Value::Object(body)
}

/// Assert that `access_token` still identifies `username` through the reader that names
/// its caller by access token alone.
async fn access_token_identifies(
    router: &MultiServiceRouter,
    case: &str,
    access_token: &str,
    username: &str,
) {
    let read = ok(router, "GetUser", &json!({ "AccessToken": access_token })).await;
    assert_eq!(
        read["Username"].as_str(),
        Some(username),
        "case {case:?}: the access token must identify the stored user, got {read}"
    );
}

/// Assert that `access_token` authorizes nothing any more.
///
/// A token this emulator issued and a revocation has since invalidated is refused AS
/// revoked — the sentence `GlobalSignOut` documents, "Amazon Cognito returns an
/// `Access Token has been revoked` error when your app attempts to authorize a user
/// pools API request with a revoked access token" — rather than with the refusal of a
/// value that resolves to no access token at all.
async fn access_token_revoked(router: &MultiServiceRouter, case: &str, access_token: &str) {
    refused(
        router,
        case,
        "GetUser",
        &json!({ "AccessToken": access_token }),
        400,
        "NotAuthorizedException",
        "Access Token has been revoked",
    )
    .await;
}

/// Assert that `refresh_token` cannot be exchanged for fresh tokens, by either of the
/// two operations a refresh token authorizes: the refresh flow of `InitiateAuth` and
/// `GetTokensFromRefreshToken`.
///
/// `rotates` says whether the app client rotates its refresh tokens, because such a
/// client does not serve the `InitiateAuth` flow at all — it "isn't enabled for the user
/// pool client" (`UnsupportedOperationException` in this service's model) — so there the
/// flow is withdrawn before any token is resolved and the revocation is reported by
/// `GetTokensFromRefreshToken` alone.
async fn refresh_token_revoked(
    router: &MultiServiceRouter,
    case: &str,
    fixture: &Fixture,
    refresh_token: &str,
    rotates: bool,
) {
    let (code, message) = if rotates {
        (
            "UnsupportedOperationException",
            "This API does not support refresh token rotation",
        )
    } else {
        ("NotAuthorizedException", "Refresh Token has been revoked")
    };
    refused(
        router,
        case,
        "InitiateAuth",
        &refresh_sign_in_body(fixture, refresh_token),
        400,
        code,
        message,
    )
    .await;
    refused(
        router,
        case,
        REFRESH,
        &refresh_body(fixture, refresh_token),
        400,
        "NotAuthorizedException",
        "Refresh Token has been revoked",
    )
    .await;
}

/// One row of the lineage table: what the sign-in did before the revocation, and which
/// of its refresh tokens the revocation names.
struct LineageRow {
    case: &'static str,
    /// The app client's `RefreshTokenRotation`.
    rotation: Option<Value>,
    /// Whether the sign-in's refresh token is exchanged for fresh tokens before the
    /// revocation, so the lineage holds tokens that token GENERATED.
    refresh_first: bool,
    /// Whether the refresh the row makes rotates the submitted refresh token out, so
    /// the lineage gains a second refresh token.
    rotates: bool,
    /// Whether the revocation names the LAST refresh token of the lineage (the one a
    /// rotation handed out) rather than the sign-in's own.
    revoke_newest: bool,
}

/// Revoking a refresh token revokes every token of the sign-in it belongs to: the ones
/// minted at the same time as it, the ones a refresh with it generated, and the refresh
/// token a rotation put in its place.
#[tokio::test]
async fn revoking_a_refresh_token_revokes_its_whole_sign_in() {
    let rows = [
        LineageRow {
            case: "a bare sign-in, revoking the token it issued",
            rotation: None,
            refresh_first: false,
            rotates: false,
            revoke_newest: false,
        },
        LineageRow {
            case: "a refresh with rotation off, revoking the sign-in's token",
            rotation: Some(json!({ "Feature": "DISABLED" })),
            refresh_first: true,
            rotates: false,
            revoke_newest: false,
        },
        LineageRow {
            // The published maximum of `RetryGracePeriodSeconds` (range 0..60), so the
            // rotated-out token is still live when the revocation names it.
            case: "a rotating refresh, revoking the rotated-out token",
            rotation: Some(json!({ "Feature": "ENABLED", "RetryGracePeriodSeconds": 60 })),
            refresh_first: true,
            rotates: true,
            revoke_newest: false,
        },
        LineageRow {
            case: "a rotating refresh, revoking the token the rotation issued",
            rotation: Some(json!({ "Feature": "ENABLED", "RetryGracePeriodSeconds": 60 })),
            refresh_first: true,
            rotates: true,
            revoke_newest: true,
        },
        LineageRow {
            case: "a client that holds a secret",
            rotation: None,
            refresh_first: true,
            rotates: false,
            revoke_newest: false,
        },
    ];

    for row in rows {
        let case = row.case;
        let router = router();
        let fixture = pool_with_client(
            &router,
            "revoke-pool",
            &ClientSetup {
                rotation: row.rotation.clone(),
                generate_secret: case == "a client that holds a secret",
                enable_token_revocation: None,
            },
        )
        .await;
        create_confirmed_user(&router, &fixture.user_pool_id, "alice").await;

        let signed_in = sign_in(
            &router,
            &fixture.client_id,
            fixture.client_secret.as_deref(),
            "alice",
        )
        .await;
        let mut access_tokens = vec![token(case, &signed_in, "AccessToken")];
        let mut refresh_tokens = vec![token(case, &signed_in, "RefreshToken")];

        if row.refresh_first {
            let refreshed = ok(
                &router,
                REFRESH,
                &refresh_body(&fixture, &refresh_tokens[0].clone()),
            )
            .await;
            let result = &refreshed["AuthenticationResult"];
            access_tokens.push(token(case, result, "AccessToken"));
            if let Some(rotated) = result["RefreshToken"].as_str() {
                refresh_tokens.push(rotated.to_string());
            }
        }
        assert_eq!(
            refresh_tokens.len() > 1,
            row.rotates,
            "case {case:?}: expected a rotated refresh token present={}, got {} refresh token(s)",
            row.rotates,
            refresh_tokens.len()
        );

        // Every token of the sign-in is live before the revocation.
        for access_token in &access_tokens {
            access_token_identifies(&router, case, access_token, "alice").await;
        }

        let revoked = if row.revoke_newest {
            refresh_tokens.last().expect("a refresh token").clone()
        } else {
            refresh_tokens.first().expect("a refresh token").clone()
        };
        let answer = ok(&router, REVOKE, &revoke_body(&fixture, &revoked)).await;
        assert_eq!(
            answer,
            Value::Object(Map::new()),
            "case {case:?}: RevokeToken models an empty response, got {answer}"
        );

        // Afterwards NOTHING of that sign-in authorizes anything.
        for access_token in &access_tokens {
            access_token_revoked(&router, case, access_token).await;
        }
        for refresh_token in &refresh_tokens {
            refresh_token_revoked(&router, case, &fixture, refresh_token, row.rotates).await;
        }
    }
}

/// A revocation reaches the sign-in its token belongs to and nothing else: another
/// sign-in of the same user on the same app client, a sign-in of another user, and a
/// sign-in on another app client of the same pool all stay in force.
#[tokio::test]
async fn a_revocation_reaches_only_the_sign_in_it_names() {
    let case = "one sign-in revoked out of four";
    let router = router();
    let fixture = pool_with_client(&router, "scoped-revoke-pool", &ClientSetup::default()).await;
    create_confirmed_user(&router, &fixture.user_pool_id, "alice").await;
    create_confirmed_user(&router, &fixture.user_pool_id, "bob").await;
    let (other_client_id, _) = add_client(
        &router,
        &fixture.user_pool_id,
        &ClientSetup::default(),
    )
    .await;
    let other_client = Fixture {
        user_pool_id: fixture.user_pool_id.clone(),
        client_id: other_client_id.clone(),
        client_secret: None,
    };

    let revoked_sign_in = sign_in(&router, &fixture.client_id, None, "alice").await;
    let kept_sign_in = sign_in(&router, &fixture.client_id, None, "alice").await;
    let bob_sign_in = sign_in(&router, &fixture.client_id, None, "bob").await;
    let other_client_sign_in = sign_in(&router, &other_client_id, None, "alice").await;

    ok(
        &router,
        REVOKE,
        &revoke_body(&fixture, &token(case, &revoked_sign_in, "RefreshToken")),
    )
    .await;

    access_token_revoked(&router, case, &token(case, &revoked_sign_in, "AccessToken")).await;
    refresh_token_revoked(
        &router,
        case,
        &fixture,
        &token(case, &revoked_sign_in, "RefreshToken"),
        false,
    )
    .await;

    for (who, sign_in_result, holder) in [
        ("alice's other sign-in", &kept_sign_in, &fixture),
        ("bob's sign-in", &bob_sign_in, &fixture),
        (
            "alice's sign-in on the other app client",
            &other_client_sign_in,
            &other_client,
        ),
    ] {
        let username = if who == "bob's sign-in" { "bob" } else { "alice" };
        access_token_identifies(
            &router,
            who,
            &token(who, sign_in_result, "AccessToken"),
            username,
        )
        .await;
        let again = ok(
            &router,
            "InitiateAuth",
            &refresh_sign_in_body(holder, &token(who, sign_in_result, "RefreshToken")),
        )
        .await;
        assert!(
            again["AuthenticationResult"]["AccessToken"]
                .as_str()
                .is_some_and(|token| !token.is_empty()),
            "case {who:?}: an untouched refresh token must still refresh, got {again}"
        );
    }
}

/// Revoking the same refresh token twice is the no-op the second call should be: the
/// lineage is already revoked, so the answer is the same empty 200.
#[tokio::test]
async fn a_second_revocation_of_the_same_token_still_succeeds() {
    let case = "the same refresh token revoked twice";
    let router = router();
    let fixture = pool_with_client(&router, "idempotent-revoke-pool", &ClientSetup::default()).await;
    create_confirmed_user(&router, &fixture.user_pool_id, "alice").await;
    let signed_in = sign_in(&router, &fixture.client_id, None, "alice").await;
    let refresh_token = token(case, &signed_in, "RefreshToken");

    for attempt in 1..=2 {
        let answer = ok(&router, REVOKE, &revoke_body(&fixture, &refresh_token)).await;
        assert_eq!(
            answer,
            Value::Object(Map::new()),
            "case {case:?}: attempt {attempt} must answer the empty response, got {answer}"
        );
    }
    refresh_token_revoked(&router, case, &fixture, &refresh_token, false).await;
}

/// Which token a row of the token-type table presents.
enum Presented {
    /// A value this emulator never handed out.
    Unissued,
    /// The named member of the sign-in on the app client under test.
    SignInMember(&'static str),
    /// The refresh token of a sign-in on ANOTHER app client of the same pool.
    OtherClientRefreshToken,
}

/// One row of the token-type table: what the request presents, and whether this app
/// client issued a token of an unsupported TYPE for it.
struct TokenTypeRow {
    case: &'static str,
    token: Presented,
    /// Whether the call is refused as an unsupported token type, rather than served as
    /// the no-op a token this app client did not issue is.
    unsupported: bool,
}

/// A token of this app client that is not a refresh token is refused as the unsupported
/// token type it is, while a value this app client issued no token for revokes nothing
/// and is still served.
#[tokio::test]
async fn only_a_refresh_token_of_this_app_client_is_revocable() {
    let rows = [
        TokenTypeRow {
            case: "a value this emulator never issued",
            token: Presented::Unissued,
            unsupported: false,
        },
        TokenTypeRow {
            case: "the sign-in's access token",
            token: Presented::SignInMember("AccessToken"),
            unsupported: true,
        },
        TokenTypeRow {
            case: "the sign-in's id token",
            token: Presented::SignInMember("IdToken"),
            unsupported: true,
        },
        TokenTypeRow {
            case: "a refresh token of another app client of the same pool",
            token: Presented::OtherClientRefreshToken,
            unsupported: false,
        },
    ];

    let router = router();
    let fixture = pool_with_client(&router, "token-type-pool", &ClientSetup::default()).await;
    create_confirmed_user(&router, &fixture.user_pool_id, "alice").await;
    let (other_client_id, _) =
        add_client(&router, &fixture.user_pool_id, &ClientSetup::default()).await;
    let other_client = Fixture {
        user_pool_id: fixture.user_pool_id.clone(),
        client_id: other_client_id.clone(),
        client_secret: None,
    };
    let signed_in = sign_in(&router, &fixture.client_id, None, "alice").await;
    let other_sign_in = sign_in(&router, &other_client_id, None, "alice").await;

    for row in rows {
        let case = row.case;
        let presented = match row.token {
            Presented::Unissued => UNISSUED_TOKEN.to_string(),
            Presented::SignInMember(member) => token(case, &signed_in, member),
            Presented::OtherClientRefreshToken => token(case, &other_sign_in, "RefreshToken"),
        };
        let body = revoke_body(&fixture, &presented);
        if row.unsupported {
            refused(
                &router,
                case,
                REVOKE,
                &body,
                400,
                "UnsupportedTokenTypeException",
                "Unsupported token type",
            )
            .await;
        } else {
            let answer = ok(&router, REVOKE, &body).await;
            assert_eq!(
                answer,
                Value::Object(Map::new()),
                "case {case:?}: a token this app client did not issue is served and revokes \
                 nothing, got {answer}"
            );
        }
    }

    // None of the rows revoked anything: the sign-in's own tokens are still in force,
    // and so is the other app client's refresh token one row named.
    access_token_identifies(
        &router,
        "after the rows",
        &token("after the rows", &signed_in, "AccessToken"),
        "alice",
    )
    .await;
    for (case, holder, refresh_token) in [
        (
            "this app client's refresh token",
            &fixture,
            token("after the rows", &signed_in, "RefreshToken"),
        ),
        (
            "the other app client's refresh token",
            &other_client,
            token("after the rows", &other_sign_in, "RefreshToken"),
        ),
    ] {
        let again = ok(&router, REFRESH, &refresh_body(holder, &refresh_token)).await;
        assert!(
            again["AuthenticationResult"]["AccessToken"]
                .as_str()
                .is_some_and(|token| !token.is_empty()),
            "case {case:?}: it must still refresh, got {again}"
        );
    }
}

/// The request has to authenticate as the app client it names, and that app client has
/// to serve this operation at all.
#[tokio::test]
async fn the_app_client_must_authenticate_and_serve_revocation() {
    let router = router();

    // An app client that holds a secret: the request proves it holds that secret.
    let with_secret = pool_with_client(
        &router,
        "client-auth-pool",
        &ClientSetup {
            generate_secret: true,
            ..ClientSetup::default()
        },
    )
    .await;
    create_confirmed_user(&router, &with_secret.user_pool_id, "alice").await;
    let secret = with_secret
        .client_secret
        .clone()
        .expect("a generated client secret");
    let signed_in = sign_in(&router, &with_secret.client_id, Some(&secret), "alice").await;
    let refresh_token = token("a client that holds a secret", &signed_in, "RefreshToken");

    refused(
        &router,
        "no ClientSecret presented",
        REVOKE,
        &json!({ "ClientId": with_secret.client_id, "Token": refresh_token }),
        400,
        "UnauthorizedException",
        "Invalid client secret.",
    )
    .await;
    refused(
        &router,
        "the wrong ClientSecret",
        REVOKE,
        &json!({
            "ClientId": with_secret.client_id,
            "Token": refresh_token,
            "ClientSecret": WRONG_CLIENT_SECRET,
        }),
        400,
        "UnauthorizedException",
        "Invalid client secret.",
    )
    .await;
    refused(
        &router,
        "a ClientId no pool holds",
        REVOKE,
        &json!({
            "ClientId": UNKNOWN_CLIENT_ID,
            "Token": refresh_token,
        }),
        400,
        "UnauthorizedException",
        "Invalid client id.",
    )
    .await;
    // The refused calls revoked nothing, and the right secret serves the revocation.
    ok(&router, REVOKE, &revoke_body(&with_secret, &refresh_token)).await;
    refresh_token_revoked(
        &router,
        "a client that holds a secret",
        &with_secret,
        &refresh_token,
        false,
    )
    .await;

    // An app client with `EnableTokenRevocation` off serves this operation for no token
    // at all, and its tokens stay in force.
    let no_revocation = pool_with_client(
        &router,
        "revocation-off-pool",
        &ClientSetup {
            enable_token_revocation: Some(false),
            ..ClientSetup::default()
        },
    )
    .await;
    create_confirmed_user(&router, &no_revocation.user_pool_id, "alice").await;
    let signed_in = sign_in(&router, &no_revocation.client_id, None, "alice").await;
    let case = "an app client with token revocation off";
    let live_refresh = token(case, &signed_in, "RefreshToken");
    refused(
        &router,
        case,
        REVOKE,
        &revoke_body(&no_revocation, &live_refresh),
        400,
        FEATURE_DISABLED_CODE,
        FEATURE_DISABLED_MESSAGE,
    )
    .await;
    access_token_identifies(&router, case, &token(case, &signed_in, "AccessToken"), "alice").await;
}

/// Which value a row of the feature-gate table submits as `Token`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum GatedToken {
    /// The sign-in's own refresh token, the one value this operation revokes.
    Refresh,
    /// The access token minted beside it, a token of this app client that is not a
    /// refresh token.
    Access,
    /// The id token minted beside it.
    Id,
    /// A well-formed value this emulator issued to nobody.
    Unissued,
    /// A refresh token ANOTHER app client of the same pool issued.
    OtherClientRefresh,
}

/// One row of the feature-gate table: how the app client's stored
/// `EnableTokenRevocation` came to hold the value it holds, whether the app client
/// authenticates with a secret, and which value the revocation names.
struct FeatureGateRow {
    case: &'static str,
    /// `EnableTokenRevocation` at create time; `None` leaves the member unset, which
    /// activates token revocation.
    created_with: Option<bool>,
    /// The `EnableTokenRevocation` an `UpdateUserPoolClient` then writes, when the row
    /// makes one: `Some(None)` is an update that omits the member.
    updated_to: Option<Option<bool>>,
    /// Whether the app client holds a secret, which the revocation then presents.
    generate_secret: bool,
    token: GatedToken,
}

/// Whether the app client the row configures ends up with token revocation activated.
///
/// "If you don't include this parameter, token revocation is automatically activated"
/// (`EnableTokenRevocation` in this service's model), on the create path and on the
/// update path alike, and an update REPLACES the member, so the last write wins.
fn revocation_activated(row: &FeatureGateRow) -> bool {
    match row.updated_to {
        Some(updated) => updated.unwrap_or(true),
        None => row.created_with.unwrap_or(true),
    }
}

/// An app client whose stored configuration does not activate the feature this
/// operation needs refuses it with `UnsupportedOperationException` and ONE fixed
/// sentence, before the submitted `Token` is resolved at all — so the refusal is the
/// same whatever that value names, and nothing is revoked. Activate the feature again
/// and the same request is decided by the value instead.
#[tokio::test]
async fn an_app_client_without_the_feature_refuses_with_the_fixed_sentence() {
    let rows = [
        FeatureGateRow {
            case: "revocation off at create, the sign-in's own refresh token",
            created_with: Some(false),
            updated_to: None,
            generate_secret: false,
            token: GatedToken::Refresh,
        },
        FeatureGateRow {
            case: "revocation off at create, the access token minted beside it",
            created_with: Some(false),
            updated_to: None,
            generate_secret: false,
            token: GatedToken::Access,
        },
        FeatureGateRow {
            case: "revocation off at create, the id token minted beside it",
            created_with: Some(false),
            updated_to: None,
            generate_secret: false,
            token: GatedToken::Id,
        },
        FeatureGateRow {
            case: "revocation off at create, a value this emulator issued no token for",
            created_with: Some(false),
            updated_to: None,
            generate_secret: false,
            token: GatedToken::Unissued,
        },
        FeatureGateRow {
            case: "revocation off at create, another app client's refresh token",
            created_with: Some(false),
            updated_to: None,
            generate_secret: false,
            token: GatedToken::OtherClientRefresh,
        },
        FeatureGateRow {
            case: "revocation off at create, on an app client that holds a secret",
            created_with: Some(false),
            updated_to: None,
            generate_secret: true,
            token: GatedToken::Refresh,
        },
        FeatureGateRow {
            case: "revocation switched off by an update",
            created_with: None,
            updated_to: Some(Some(false)),
            generate_secret: false,
            token: GatedToken::Refresh,
        },
        FeatureGateRow {
            case: "revocation off at create and switched back on by an update",
            created_with: Some(false),
            updated_to: Some(Some(true)),
            generate_secret: false,
            token: GatedToken::Refresh,
        },
        FeatureGateRow {
            case: "revocation off at create, then an update that names no \
                   EnableTokenRevocation",
            created_with: Some(false),
            updated_to: Some(None),
            generate_secret: false,
            token: GatedToken::Refresh,
        },
        FeatureGateRow {
            case: "the member left unset at create, the sign-in's own refresh token",
            created_with: None,
            updated_to: None,
            generate_secret: false,
            token: GatedToken::Refresh,
        },
        FeatureGateRow {
            case: "revocation on explicitly, the access token minted beside it",
            created_with: Some(true),
            updated_to: None,
            generate_secret: false,
            token: GatedToken::Access,
        },
    ];

    for row in rows {
        let case = row.case;
        let router = router();
        let fixture = pool_with_client(
            &router,
            "feature-gate-pool",
            &ClientSetup {
                rotation: None,
                generate_secret: row.generate_secret,
                enable_token_revocation: row.created_with,
            },
        )
        .await;
        create_confirmed_user(&router, &fixture.user_pool_id, "alice").await;
        let signed_in = sign_in(
            &router,
            &fixture.client_id,
            fixture.client_secret.as_deref(),
            "alice",
        )
        .await;
        let access_token = token(case, &signed_in, "AccessToken");

        // The value the revocation will name. The sign-ins happen while the app client
        // still configures the auth flows it was created with, before any update.
        let (presented, other_access_token) = match row.token {
            GatedToken::Refresh => (token(case, &signed_in, "RefreshToken"), None),
            GatedToken::Access => (access_token.clone(), None),
            GatedToken::Id => (token(case, &signed_in, "IdToken"), None),
            GatedToken::Unissued => (UNISSUED_TOKEN.to_string(), None),
            GatedToken::OtherClientRefresh => {
                let (other_client_id, _) =
                    add_client(&router, &fixture.user_pool_id, &ClientSetup::default()).await;
                let other_sign_in = sign_in(&router, &other_client_id, None, "alice").await;
                (
                    token(case, &other_sign_in, "RefreshToken"),
                    Some(token(case, &other_sign_in, "AccessToken")),
                )
            }
        };

        // The gate reads the configuration the app client holds NOW, so a row that
        // updates it rewrites the member (and names the flows again, which an update
        // replaces like every other member).
        if let Some(enable_token_revocation) = row.updated_to {
            let mut body = Map::new();
            body.insert("UserPoolId".to_string(), json!(fixture.user_pool_id));
            body.insert("ClientId".to_string(), json!(fixture.client_id));
            body.insert(
                "ExplicitAuthFlows".to_string(),
                json!(["ALLOW_USER_PASSWORD_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]),
            );
            if let Some(enabled) = enable_token_revocation {
                body.insert("EnableTokenRevocation".to_string(), json!(enabled));
            }
            ok(&router, "UpdateUserPoolClient", &Value::Object(body)).await;
        }

        let body = revoke_body(&fixture, &presented);
        if revocation_activated(&row) {
            // With the feature activated the submitted value decides: a refresh token of
            // this app client is revoked, a token of another type is the unsupported type
            // it is, and a value this app client issued no token for is served as a
            // no-op.
            match row.token {
                GatedToken::Access | GatedToken::Id => {
                    refused(
                        &router,
                        case,
                        REVOKE,
                        &body,
                        400,
                        "UnsupportedTokenTypeException",
                        "Unsupported token type",
                    )
                    .await;
                    access_token_identifies(&router, case, &access_token, "alice").await;
                }
                GatedToken::Refresh => {
                    ok(&router, REVOKE, &body).await;
                    access_token_revoked(&router, case, &access_token).await;
                }
                GatedToken::Unissued | GatedToken::OtherClientRefresh => {
                    ok(&router, REVOKE, &body).await;
                    access_token_identifies(&router, case, &access_token, "alice").await;
                }
            }
        } else {
            refused(
                &router,
                case,
                REVOKE,
                &body,
                400,
                FEATURE_DISABLED_CODE,
                FEATURE_DISABLED_MESSAGE,
            )
            .await;
            // A refused request revoked nothing: the sign-in's tokens stay in force.
            access_token_identifies(&router, case, &access_token, "alice").await;
        }

        // The other app client one row names is untouched either way.
        if let Some(other_access_token) = other_access_token {
            access_token_identifies(&router, case, &other_access_token, "alice").await;
        }
    }
}
